/**
 * @brief 从常开循环 DMA1_CHANNEL6 非破坏性增量抽取 USART2 接收字节并推入协议环形队列
 */
__attribute__((section("RAMCODE1")))
void usart2_rx_dma_drain(void)
{
    uint8_t *const dma_buf = wk_usart2_rx_dma_buf_get();
    /* 保存 PRIMASK 并关中断，防止 USART2_IRQHandler 与主循环重入竞争读索引 */
    const uint32_t primask = __get_PRIMASK();
    __disable_irq();

    /* 及时清除 ROERR/FERR/NERR/BFF 并确保循环 DMA1_CHANNEL6 使能，防止错误锁死接收 */
    (void)minimc_usart2_clear_rx_errors();
    if (DMA1_CHANNEL6->ctrl_bit.chen == 0U)
    {
        dma_channel_enable(DMA1_CHANNEL6, TRUE);
    }

    const uint16_t rem = dma_data_number_get(DMA1_CHANNEL6);
    const uint16_t wr_idx = (rem <= USART2_RX_DMA_BUF_SIZE)
        ? (uint16_t)((USART2_RX_DMA_BUF_SIZE - rem) % USART2_RX_DMA_BUF_SIZE)
        : 0U;
    const uint16_t rd_idx = s_usart2_dma_rd_idx;
    if (wr_idx != rd_idx)
    {
        if (wr_idx > rd_idx)
        {
            const uint16_t seg_len = (uint16_t)(wr_idx - rd_idx);
            minimc_proto_push_ap_rx(&dma_buf[rd_idx], seg_len);
            gui_try_capture_dgus_frame(dma_buf, rd_idx, seg_len);
        }
        else
        {
            const uint16_t tail_len = (uint16_t)(USART2_RX_DMA_BUF_SIZE - rd_idx);
            minimc_proto_push_ap_rx(&dma_buf[rd_idx], tail_len);
            if (wr_idx > 0U)
            {
                minimc_proto_push_ap_rx(&dma_buf[0], wr_idx);
            }
            gui_try_capture_dgus_frame(dma_buf, rd_idx, (uint16_t)(tail_len + wr_idx));
        }
        s_usart2_dma_rd_idx = wr_idx;
    }
    if (primask == 0U)
    {
        __enable_irq();
    }
}

/**
 * @brief 在关中断保护下清除 USART2 全部错误与 IDLE 标志并将循环 DMA 读指针同步至当前硬件写位置
 */
__attribute__((section("RAMCODE1")))
void usart2_rx_dma_reset(void)
{
    const uint32_t primask = __get_PRIMASK();
    __disable_irq();

    /* 清除全部接收错误与 IDLEF 标志，并保证循环 DMA1_CHANNEL6 保持使能 */
    (void)minimc_usart2_clear_rx_errors();
    if (usart_flag_get(USART2, USART_IDLEF_FLAG) != RESET)
    {
        usart_flag_clear(USART2, USART_IDLEF_FLAG);
    }
    if (DMA1_CHANNEL6->ctrl_bit.chen == 0U)
    {
        dma_channel_enable(DMA1_CHANNEL6, TRUE);
    }
    const uint16_t rem = dma_data_number_get(DMA1_CHANNEL6);
    s_usart2_dma_rd_idx = (rem <= USART2_RX_DMA_BUF_SIZE)
        ? (uint16_t)((USART2_RX_DMA_BUF_SIZE - rem) % USART2_RX_DMA_BUF_SIZE)
        : 0U;
    usart2_rx_len = 0U;
    rxdata_complete = false;

    if (primask == 0U)
    {
        __enable_irq();
    }
}

