        helix::ui::queue_update("aisoc_snapshot", [this, snap]() {
            if (lv_subject_t* s = lv_xml_get_subject(nullptr, "aisoc_ap_version")) {
                lv_subject_copy_string(s, helix::aisoc::format_ap_version(snap.ap).c_str());
            }
            if (lv_subject_t* s = lv_xml_get_subject(nullptr, "aisoc_mc_version")) {
                lv_subject_copy_string(s, helix::aisoc::format_mcu_version(snap.dm_connected, snap.mc).c_str());
            }
            if (lv_subject_t* s = lv_xml_get_subject(nullptr, "aisoc_th_version")) {
                lv_subject_copy_string(s, helix::aisoc::format_mcu_version(snap.dm_connected, snap.th).c_str());
            }
            if (snap.ap.valid) get_printer_state().set_os_version(snap.ap.product_version);
            get_printer_state().set_klipper_version(helix::aisoc::format_mcu_version(snap.dm_connected, snap.mc));
            get_printer_state().set_moonraker_version(helix::aisoc::format_mcu_version(snap.dm_connected, snap.th));
            if (!snap.dm_connected || !snap.mc.online) {
                get_printer_state().set_printer_connection_state(0, snap.dm_connected ? "MCU Offline" : "DM Offline");
            } else if (snap.mc.is_boot_mode) {
                get_printer_state().set_printer_connection_state(1, "MC Bootloader");
                get_printer_state().set_klippy_state(helix::KlippyState::ERROR);
            } else if (snap.estop_latched) {
                get_printer_state().set_printer_connection_state(2, "E-Stop Latched");
                get_printer_state().set_klippy_state(helix::KlippyState::SHUTDOWN);
            } else {
                get_printer_state().set_printer_connection_state(2, "Connected");
                get_printer_state().set_klippy_state(helix::KlippyState::READY);
            }
        });
    });
    m_aisoc->set_estop_callback([](const helix::aisoc::AisocEstopResult& res) {
        helix::ui::queue_update("aisoc_estop", [res]() {
            if (res.outcome == helix::aisoc::AisocEstopOutcome::CONFIRMED) {
                ToastManager::instance().show(ToastSeverity::WARNING, "设备已确认急停", 5000);
            } else if (res.outcome == helix::aisoc::AisocEstopOutcome::BACKEND_BUSY) {
                ToastManager::instance().show(ToastSeverity::ERROR, "后台已锁定 (BUSY)", 5000);
            } else {
                ToastManager::instance().show(ToastSeverity::ERROR, res.detail.c_str(), 5000);
            }
        });
    });
    // 启动 AISoC 后台线程前提前初始化关于页 Subject 与回调，避免启动期快照触发缺失 Subject 警告，
