/**
 * @brief 检查并清除 USART2 全部接收错误标志（ROERR/FERR/NERR 与写清的 BFF）
 * @return true 至少清除了一类错误标志，false 当前无接收错误标志置位
 */
bool minimc_usart2_clear_rx_errors(void)
{
    bool cleared = false;
    const bool has_roerr = (usart_flag_get(USART2, USART_ROERR_FLAG) != RESET);
    const bool has_ferr = (usart_flag_get(USART2, USART_FERR_FLAG) != RESET);
    const bool has_nerr = (usart_flag_get(USART2, USART_NERR_FLAG) != RESET);
    /* ROERR/FERR/NERR 在 AT32F435 上均通过读 STS+DT 序列统一清除，单次 if 避免测试桩死循环 */
    if (has_roerr || has_ferr || has_nerr)
    {
        usart_flag_clear(USART2, USART_ROERR_FLAG);
        cleared = true;
    }
    /* BFF (Break 帧标志) 必须通过写 STS = ~USART_BFF_FLAG 单独清除 */
    if (usart_flag_get(USART2, USART_BFF_FLAG) != RESET)
    {
        usart_flag_clear(USART2, USART_BFF_FLAG);
        cleared = true;
    }
    return cleared;
}

/**
 * @brief 复位 USART2 接收错误与 IDLE 标志、同步丢弃循环 DMA 历史噪声并清空 AP 协议解析/环形状态
 */
void minimc_proto_reset_rx_channel(void)
{
    (void)minimc_usart2_clear_rx_errors();
    if (usart_flag_get(USART2, USART_IDLEF_FLAG) != RESET)
    {
        usart_flag_clear(USART2, USART_IDLEF_FLAG);
    }
    usart2_rx_dma_reset();
    parser_init(&s_ap_parser);
    ring_init(&s_ap_ring);
}

/**
 * @brief 从 AP 接收环形队列按 600B 预算拉取字节并推进流式帧解析器（前置清错与增量抽取 DMA1_CHANNEL6）
 */
static void drain_ap_rx(void)
{
    (void)minimc_usart2_clear_rx_errors();
    usart2_rx_dma_drain();
    uint8_t byte = 0U;
    uint16_t budget = 600U;
    while ((budget > 0U) && ring_pop(&s_ap_ring, &byte))
    {
        budget--;
        bool frame_ready = false;
        if (parser_step(&s_ap_parser, byte, &frame_ready) && frame_ready)
        {
            const uint16_t plen = (uint16_t)s_ap_parser.buf[10] | (uint16_t)((uint16_t)s_ap_parser.buf[11] << 8U);
            const uint16_t f_len = (uint16_t)(MINIMC_HEADER_SIZE + plen + MINIMC_CRC_SIZE);
            handle_ap_frame(s_ap_parser.buf, f_len);
        }
    }
}

