Heater_reset(&Platform, HBP); // 重置平台加热器
setup(); // Marlin固件初始化
poweroff_startup(); // 断电启动处理
Set_Fan_Power(0,0);	//设置风扇速度
/* add user code end 2 */

// power_off_save_handler(); // 断电保存处理
//tmr_channel_value_set(TMR3, TMR_SELECT_CHANNEL_1, 255);		//关闭EX1PWM输出
Led_Power_On(); // LED开机
BottomBox_Fans_On(); // 开启底部机箱风扇
/* 丢弃 eeprom_Init()/Board_init()/setup() 长初始化期间 USART2 吃入的杂波字节与错误标志 */
minimc_proto_reset_rx_channel();
while(1) // 主循环
{
	/* add user code begin 3 */
	usbh_loop_handler(&otg_core_struct.host);
	th_upgrade_mgr_poll(wk_timebase_get());
	/* 主循环轮询处理 SoC 与 TH 板的 MiniMCProto 协议帧及非阻塞调试输出 */
