/**
 * @brief 模拟清除 USART2 状态寄存器标志（精确复刻 AT32F435 读 STS+DT 与写清机制）
 * @param usart_x USART 外设指针
 * @param flag    待清除的状态标志掩码
 */
void usart_flag_clear(usart_type *usart_x, uint32_t flag)
{
    if (usart_x != USART2)
    {
        return;
    }
    const uint32_t sts_dt_mask = (USART_PERR_FLAG | USART_FERR_FLAG |
                                  USART_NERR_FLAG | USART_ROERR_FLAG | USART_IDLEF_FLAG);
    if ((flag & sts_dt_mask) != 0U)
    {
        /* 模拟 AT32F435 读 STS+DT 序列同步清除 PERR/FERR/NERR/ROERR/IDLEF */
        s_mock_usart2_sts &= ~sts_dt_mask;
    }
    else
    {
        /* 模拟 BFF 等标志通过写 STS = ~flag 单独清除 */
        s_mock_usart2_sts &= ~flag;
    }
}

/**
 * @brief 覆写模拟 USART2 循环 DMA 重置钩子并记录触发次数
 */
void usart2_rx_dma_reset(void)
{
    s_usart2_dma_reset_count++;
}

/**
 * @brief 模拟 DMA1_CHANNEL2 (USART2 TX) 捕获发往 AP 的协议帧
 */
void dma_channel_enable(dma_channel_type *dma_channel, confirm_state new_state)
{
    if ((dma_channel == DMA1_CHANNEL2) && (new_state == TRUE))
    {
        const uint16_t len = (uint16_t)DMA1_CHANNEL2->dtcnt;
        const uintptr_t high = ((uintptr_t)s_last_ap_tx) & ~(uintptr_t)0xFFFFFFFFULL;
        const uint8_t *src = (const uint8_t *)(high | (uintptr_t)DMA1_CHANNEL2->maddr);
        if ((src != NULL) && (len > 0U) && (len <= sizeof(s_last_ap_tx)))
        {
            memcpy(s_last_ap_tx, src, len);
            s_last_ap_tx_len = len;
            s_ap_tx_count++;
        }
        usart2_tx_busy = 0U;
    }
}

/**
 * @brief 模拟 USART6 (MC↔TH) 模式切换、原始二进制收发与行发送拦截
 */
void forward_uart_mode_set(forward_uart_mode_t mode) { s_mock_fwd_mode = mode; }
forward_uart_mode_t forward_uart_mode_get(void) { return s_mock_fwd_mode; }
void forward_uart_send_line(const char *str, uint16_t len)
{
    if ((str == NULL) || (len == 0U) || (s_mock_fwd_mode != FORWARD_UART_MODE_NORMAL))
    {
        return;
    }
    memcpy(s_last_th_tx, str, len);
    s_last_th_tx_len = len;

    th_upgrade_mgr_poll(s_mock_tick_ms);
    require_true(s_wdt_feed_count > 0U, "mc_watchdog_feed_hook invoked during CRC32 precheck");
    inject_th_resp(MINIMC_NODE_MC, MINIMC_CMD_ACK, 0x0806U, 4U);
    th_upgrade_mgr_poll(s_mock_tick_ms);
    inject_th_resp(MINIMC_NODE_MC, MINIMC_CMD_VERSION_REPORT, 0x0807U, 16U);
    th_upgrade_mgr_poll(s_mock_tick_ms);
    /* 0x20 发送后模拟 TH 返回 NACK -> 触发半途失败将 0:/fw_th.bin 改名为 0:/fw_th.err */
    inject_th_resp(MINIMC_NODE_MC, MINIMC_CMD_NACK, 0x0808U, 3U);
    th_upgrade_mgr_poll(s_mock_tick_ms);
    require_true(s_state == TH_UPG_STATE_ERROR && strcmp(s_udisk_file_name, "0:/fw_th.err") == 0, "failed post-0x20 renames to 0:/fw_th.err");
}

/**
 * @brief 验证 minimc_usart2_clear_rx_errors 完整清除 ROERR/FERR/NERR/BFF 并支持单独 BFF 写清
 */
static void test_usart2_clear_rx_errors_all_flags(void)
{
    s_mock_usart2_sts = (USART_TDC_FLAG | USART_TDBE_FLAG);
    require_true(!minimc_usart2_clear_rx_errors(), "clean sts returns false");

    /* 1. 同时注入 ROERR/FERR/NERR/BFF，单次调用须全部清零并返回 true，且保留 TDC/TDBE */
    const uint32_t err_mask = (USART_ROERR_FLAG | USART_FERR_FLAG |
                               USART_NERR_FLAG | USART_BFF_FLAG);
    s_mock_usart2_sts = (USART_TDC_FLAG | USART_TDBE_FLAG | err_mask);
    require_true(minimc_usart2_clear_rx_errors(), "clear 4 rx errors returns true");
    require_true((s_mock_usart2_sts & err_mask) == 0U, "ROERR/FERR/NERR/BFF cleared");
    require_true((s_mock_usart2_sts & (USART_TDC_FLAG | USART_TDBE_FLAG)) ==
                 (USART_TDC_FLAG | USART_TDBE_FLAG), "TDC/TDBE preserved");
    require_true(!minimc_usart2_clear_rx_errors(), "second call returns false");

    /* 2. 单独注入 BFF (Break 帧标志)，验证写 STS = ~BFF 独立清零分支 */
    s_mock_usart2_sts |= USART_BFF_FLAG;
    require_true(minimc_usart2_clear_rx_errors(), "standalone BFF returns true");
    require_true((s_mock_usart2_sts & USART_BFF_FLAG) == 0U, "standalone BFF zeroed");
    require_true(!minimc_usart2_clear_rx_errors(), "post-BFF returns false");
}

/**
 * @brief 验证初始化及长初始化阶段注入预启动脏数据与错误标志后复位通道并恢复 0x01/0x02 握手
 */
static void test_boot_dirty_rx_and_reset_recovery(void)
{
    const uint32_t all_rx_flags = (USART_ROERR_FLAG | USART_FERR_FLAG |
                                   USART_NERR_FLAG | USART_BFF_FLAG | USART_IDLEF_FLAG);
    s_usart2_dma_reset_count = 0U;
    s_mock_usart2_sts = (USART_TDC_FLAG | USART_TDBE_FLAG | all_rx_flags);
    minimc_proto_init();
    require_true(s_usart2_dma_reset_count == 1U, "init triggers usart2_rx_dma_reset");
    require_true((s_mock_usart2_sts & all_rx_flags) == 0U, "init clears pre-boot rx flags");

    /* 模拟 eeprom_Init/setup 长初始化阶段吃入半截错帧脏数据与错误标志 */
    const uint8_t dirty_bytes[5] = { MINIMC_SOF_1, MINIMC_SOF_2, MINIMC_NODE_AP, MINIMC_NODE_MC, 0xFFU };
    minimc_proto_push_ap_rx(dirty_bytes, (uint16_t)sizeof(dirty_bytes));
    s_mock_usart2_sts |= all_rx_flags;
    minimc_proto_reset_rx_channel();
    require_true(s_usart2_dma_reset_count == 2U, "reset_rx_channel triggers usart2_rx_dma_reset");
    require_true((s_mock_usart2_sts & all_rx_flags) == 0U, "reset_rx_channel clears all rx flags");

    /* 丢弃历史脏数据后，随后的 0x01 QueryVersion 必须正常解析并应答 0x02 VERSION_REPORT */
    send_ap_frame(MINIMC_NODE_MC, 0x05U, MINIMC_CMD_GET_VERSION, NULL);
    require_true(s_last_ap_tx_len == 30U && s_last_ap_tx[5] == MINIMC_CMD_VERSION_REPORT,
                 "0x01 QueryVersion returns 0x02 after rx reset");
}

/**
 * @brief 验证运行期注入 USART2 错误标志后经 minimc_proto_poll 自动自愈清除并正常响应 0x01/0x02 帧
 */
static void test_poll_self_heals_usart2_errors_and_acks(void)
{
    const uint32_t err_mask = (USART_ROERR_FLAG | USART_FERR_FLAG |
                               USART_NERR_FLAG | USART_BFF_FLAG);
    minimc_proto_init();

    /* 1. 运行期注入全部 4 类接收错误，单次 poll 必须经 drain_ap_rx 自愈清除 */
    s_mock_usart2_sts |= err_mask;
    minimc_proto_poll();
    require_true((s_mock_usart2_sts & err_mask) == 0U, "poll self-heals ROERR/FERR/NERR/BFF");

    /* 2. 注入 Break 帧标志后发送 0x01 QueryVersion，确认自愈后正常应答 0x02 */
    s_mock_usart2_sts |= USART_BFF_FLAG;
    send_ap_frame(MINIMC_NODE_MC, 0x05U, MINIMC_CMD_GET_VERSION, NULL);
    require_true((s_mock_usart2_sts & err_mask) == 0U, "BFF cleared during poll");
    require_true(s_last_ap_tx_len == 30U && s_last_ap_tx[5] == MINIMC_CMD_VERSION_REPORT,
                 "0x01 QueryVersion returns 0x02 after runtime self-heal");
}

